-- 1. regional_cells (non-US sub-national rows)
UPDATE regional_cells
SET cost_stack = jsonb_build_object(
  'rent_occupancy',         ROUND(rev_p50 * 0.1),
  'payroll_total',          ROUND(rev_p50 * 0.45),
  'cost_of_goods_sold',     ROUND(rev_p50 * 0.01),
  'utilities',              ROUND(rev_p50 * 0.02),
  'marketing_acquisition',  ROUND(rev_p50 * 0.04),
  'insurance_professional', ROUND(rev_p50 * 0.05),
  'equipment_maintenance',  ROUND(rev_p50 * 0.02),
  'regulatory_licensing',   ROUND(rev_p50 * 0.03),
  'refreshed_at',           '2026-05-24',
  'source_note',            'ABA Profile of the Legal Profession 2024 + Clio Legal Trends Report 2024. Country revenue captures local price level implicitly.',
  'grade',                  'C'
)
WHERE industry_id = 'legal_services'
  AND rev_p50 IS NOT NULL
  AND rev_p50 > 0
  AND (cost_stack IS NULL OR cost_stack->>'grade' IN ('C', 'D'));

