-- 3. extrapolated_cells (country-level fallback)
UPDATE extrapolated_cells
SET cost_stack = jsonb_build_object(
  'rent_occupancy',         ROUND(predicted_rev_per_firm * 0.1),
  'payroll_total',          ROUND(predicted_rev_per_firm * 0.45),
  'cost_of_goods_sold',     ROUND(predicted_rev_per_firm * 0.01),
  'utilities',              ROUND(predicted_rev_per_firm * 0.02),
  'marketing_acquisition',  ROUND(predicted_rev_per_firm * 0.04),
  'insurance_professional', ROUND(predicted_rev_per_firm * 0.05),
  'equipment_maintenance',  ROUND(predicted_rev_per_firm * 0.02),
  'regulatory_licensing',   ROUND(predicted_rev_per_firm * 0.03),
  'refreshed_at',           '2026-05-24',
  'source_note',            'ABA Profile of the Legal Profession 2024 + Clio Legal Trends Report 2024. Country-level extrapolation; coarser than regional_cells.',
  'grade',                  'D'
)
WHERE industry_id = 'legal_services'
  AND predicted_rev_per_firm IS NOT NULL
  AND predicted_rev_per_firm > 0
  AND (cost_stack IS NULL OR cost_stack->>'grade' IN ('C', 'D'));
